<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;
use App\Http\Resources\Api\V1\ProfileResource;
use Illuminate\Http\Request;
use Illuminate\Validation\Rule;
class ProfileController extends Controller {
 public function show(Request $request): ProfileResource { return new ProfileResource($request->user()->profile()->with(['country','category','skills','languages','experiences','catalogImages'])->firstOrFail()); }
 public function update(Request $request): ProfileResource { $profile=$request->user()->profile; $data=$request->validate(['public_name'=>['nullable','string','max:120'],'phone'=>['nullable','string','max:32'],'country_id'=>['nullable','integer','exists:countries,id'],'city'=>['nullable','string','max:120'],'region'=>['nullable','string','max:120'],'nationality'=>['nullable','string','max:100'],'professional_title'=>['nullable','string','max:160'],'professional_category_id'=>['nullable','integer','exists:professional_categories,id'],'bio'=>['nullable','string','max:3000'],'education_level'=>['nullable','string','max:100'],'years_experience'=>['nullable','integer','min:0','max:80'],'available_for_work'=>['sometimes','boolean'],'is_public'=>['sometimes','boolean'],'skill_ids'=>['sometimes','array','max:40'],'skill_ids.*'=>['integer','distinct','exists:skills,id'],'language_ids'=>['sometimes','array','max:20'],'language_ids.*'=>['integer','distinct','exists:languages,id']]);
 $skills=$data['skill_ids']??null; $languages=$data['language_ids']??null; $hasProfileChanges = count($data) > 0 || $skills !== null || $languages !== null; unset($data['skill_ids'],$data['language_ids']); if ($profile->review_status === 'approved' && $hasProfileChanges) { $data['review_status']='draft'; $data['is_public']=false; $data['reviewed_at']=null; $data['reviewed_by']=null; $data['review_note']=null; } $profile->fill($data)->save(); if($skills!==null)$profile->skills()->sync($skills); if($languages!==null)$profile->languages()->sync($languages); return new ProfileResource($profile->load(['country','category','skills','languages','experiences'])); }
 public function uploadAvatar(Request $request) { $request->validate(['avatar'=>['required','image','mimes:jpg,jpeg,png,webp','max:5120']]); $profile=$request->user()->profile; if($profile->avatar_path) \Illuminate\Support\Facades\Storage::disk('public')->delete($profile->avatar_path); $path=$request->file('avatar')->store('profiles','public'); $profile->update(['avatar_path'=>$path,'review_status'=>'draft','is_public'=>false,'reviewed_at'=>null,'reviewed_by'=>null,'review_note'=>null]); return response()->json(['message'=>'Photo enregistrée. Le profil devra être soumis à validation.','avatar_url'=>url('storage/'.$path)]); }
 public function uploadCatalog(Request $request) { $data=$request->validate(['images'=>['required','array','min:1','max:12'],'images.*'=>['required','image','mimes:jpg,jpeg,png,webp','max:5120'],'captions'=>['sometimes','array'],'captions.*'=>['nullable','string','max:180']]); $profile=$request->user()->profile; $created=[]; foreach($request->file('images',[]) as $i=>$file){ $path=$file->store('catalogues/profiles','public'); $created[]=$profile->catalogImages()->create(['uploaded_by'=>$request->user()->id,'image_path'=>$path,'caption'=>$data['captions'][$i]??null,'is_public'=>false]); } if($profile->review_status==='approved') $profile->update(['review_status'=>'draft','is_public'=>false,'reviewed_at'=>null,'reviewed_by'=>null]); return response()->json(['message'=>'Catalogue professionnel enregistré. Il sera visible publiquement après validation du profil.','data'=>$created],201); }
 public function deleteCatalogImage(Request $request,int $image) { $row=$request->user()->profile->catalogImages()->findOrFail($image); \Illuminate\Support\Facades\Storage::disk('public')->delete($row->image_path); $row->delete(); return response()->json(['message'=>'Image retirée du catalogue.']); }
 public function addExperience(Request $request) { $data=$request->validate(['job_title'=>['required','string','max:160'],'organization'=>['nullable','string','max:160'],'location'=>['nullable','string','max:160'],'started_at'=>['nullable','date'],'ended_at'=>['nullable','date','after_or_equal:started_at'],'is_current'=>['sometimes','boolean'],'description'=>['nullable','string','max:3000']]); $experience=$request->user()->profile->experiences()->create($data); return response()->json(['data'=>$experience],201); }
 public function deleteExperience(Request $request, int $experience) { $deleted=$request->user()->profile->experiences()->whereKey($experience)->delete(); abort_if(!$deleted,404); return response()->json(['message'=>'Expérience supprimée.']); }
}
